enum class big_u32 : std::uint32_t { Y = 0xFFFFFFFFu };
enum class s : int { N = -1 };
int main() {
    auto a = nlohmann::json(small_u::A);
    auto b = nlohmann::json(big_u::X);
    auto c = nlohmann::json(big_u32::Y);
